"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[312],{5312:(e,t,a)=>{a.d(t,{Z:()=>n,r:()=>i});let i=[{id:"R1",title:"The Benefits of Walking",level:"B1",topic:"Health",focusTh:"อ่านหาใจความหลัก (main idea) ของแต่ละย่อหน้า และรายละเอียดสนับสนุน",minutes:12,paragraphs:[{label:"A",text:"Walking is one of the easiest ways to stay healthy. It does not require special equipment or a gym membership, and most people can do it every day. Doctors often say that thirty minutes of walking a day is enough to make a real difference to our health."},{label:"B",text:"One important benefit is for the heart. Regular walking lowers blood pressure and reduces the risk of heart disease. It also helps people control their weight, especially when they walk quickly."},{label:"C",text:"Walking is good for the mind, too. Studies show that people who walk outside, particularly in parks, feel less stressed than people who exercise indoors. Some people say they have their best ideas while walking."},{label:"D",text:"However, many people find it difficult to walk regularly. The most common reason is a lack of time. Experts suggest small changes, such as getting off the bus one stop early or using the stairs instead of the lift."}],questionGroups:[{instructions:"Choose the correct answer.",questions:[{id:"q1",kind:"mcq",qtype:"main-idea",prompt:"What is paragraph C mainly about?",options:["Walking in parks is dangerous","Mental benefits of walking","How to walk faster"],answer:["Mental benefits of walking"],explanationTh:"ประโยคแรกของย่อหน้า (topic sentence) 'Walking is good for the mind' บอกใจความหลัก",evidence:"Walking is good for the mind, too."},{id:"q2",kind:"mcq",qtype:"detail",prompt:"According to paragraph B, walking quickly especially helps people to…",options:["sleep better","control their weight","make friends"],answer:["control their weight"],explanationTh:"'especially when they walk quickly' ขยายเรื่อง control their weight",evidence:"It also helps people control their weight, especially when they walk quickly."},{id:"q3",kind:"mcq",qtype:"detail",prompt:"What is the most common reason people do not walk regularly?",options:["Bad weather","Lack of time","Health problems"],answer:["Lack of time"],explanationTh:"The most common reason is a lack of time",evidence:"The most common reason is a lack of time."},{id:"q4",kind:"mcq",qtype:"vocab-in-context",prompt:"In paragraph D, 'suggest' is closest in meaning to…",options:["recommend","prove","refuse"],answer:["recommend"],explanationTh:"suggest = แนะนำ ใกล้เคียง recommend มากที่สุด",evidence:"Experts suggest small changes"},{id:"q5",kind:"mcq",qtype:"scanning",prompt:"How many minutes of walking a day do doctors often recommend?",options:["15","30","60"],answer:["30"],explanationTh:"ทักษะ scanning: กวาดตาหาตัวเลขในย่อหน้า A",evidence:"thirty minutes of walking a day is enough"}]}],vocab:[{en:"equipment",th:"อุปกรณ์ (นามนับไม่ได้)",example:"Walking does not require special equipment.",ipa:"/ɪˈkwɪp.mənt/",topic:"Health",level:"B1"},{en:"blood pressure",th:"ความดันโลหิต",example:"Regular walking lowers blood pressure.",topic:"Health",level:"B1"},{en:"reduce the risk of",th:"ลดความเสี่ยงของ",example:"Exercise reduces the risk of heart disease.",topic:"Health",level:"B1"}]},{id:"R2",title:"Learning Languages Online",level:"B1",topic:"Education",focusTh:"แนะนำ True / False / Not Given: แยก 'ข้อมูลขัดแย้ง' (False) กับ 'ไม่มีข้อมูล' (Not Given)",minutes:12,paragraphs:[{label:"A",text:"Over the past ten years, the number of people learning languages through apps and websites has grown quickly. Many learners like being able to study on their phones for a few minutes at a time, for example while travelling to work."},{label:"B",text:"Online courses are usually cheaper than classes at a language school, and some are completely free. However, free apps often focus on vocabulary and simple sentences, and they rarely give learners the chance to have real conversations."},{label:"C",text:"Research suggests that learners who combine an app with regular speaking practice make faster progress than those who use an app alone. Speaking with another person forces learners to produce language, not just recognise it."},{label:"D",text:"Teachers do not think apps will replace classrooms. Instead, they expect that most students in the future will use a mixture of online and face-to-face learning."}],questionGroups:[{instructions:"Do the following statements agree with the information in the passage? Choose TRUE, FALSE or NOT GIVEN.",questions:[{id:"q1",kind:"mcq",qtype:"tfng",prompt:"More people use language apps now than ten years ago.",options:["True","False","Not Given"],answer:["True"],explanationTh:"'has grown quickly' = เพิ่มขึ้น ตรงกับข้อความ → TRUE (paraphrase: grown = more people)",evidence:"the number of people learning languages through apps and websites has grown quickly"},{id:"q2",kind:"mcq",qtype:"tfng",prompt:"All online language courses cost money.",options:["True","False","Not Given"],answer:["False"],explanationTh:"บทความบอกว่า 'some are completely free' ขัดแย้งกับ 'All … cost money' → FALSE",evidence:"some are completely free"},{id:"q3",kind:"mcq",qtype:"tfng",prompt:"Free apps give learners many chances to have real conversations.",options:["True","False","Not Given"],answer:["False"],explanationTh:"'rarely give' (แทบไม่ให้) ขัดแย้งกับ 'many chances' → FALSE",evidence:"they rarely give learners the chance to have real conversations"},{id:"q4",kind:"mcq",qtype:"tfng",prompt:"Most language app users are university students.",options:["True","False","Not Given"],answer:["Not Given"],explanationTh:"บทความไม่ได้พูดถึงว่าผู้ใช้ส่วนใหญ่เป็นใคร ห้ามเดาจากความรู้ตัวเอง → NOT GIVEN",evidence:"(ไม่มีข้อมูลเรื่องนี้ในบทความ)"},{id:"q5",kind:"mcq",qtype:"tfng",prompt:"Combining an app with speaking practice leads to quicker progress.",options:["True","False","Not Given"],answer:["True"],explanationTh:"faster progress = quicker progress (paraphrase) → TRUE",evidence:"learners who combine an app with regular speaking practice make faster progress"},{id:"q6",kind:"mcq",qtype:"tfng",prompt:"Teachers believe classrooms will disappear in the future.",options:["True","False","Not Given"],answer:["False"],explanationTh:"'Teachers do not think apps will replace classrooms' ขัดแย้ง → FALSE",evidence:"Teachers do not think apps will replace classrooms."}]}],vocab:[{en:"combine",th:"รวม, ผสม",example:"Combine an app with speaking practice.",ipa:"/kəmˈbaɪn/",topic:"Education",level:"B1"},{en:"make progress",th:"มีความก้าวหน้า",example:"Learners make faster progress with practice.",topic:"Education",level:"B1"},{en:"face-to-face",th:"แบบเจอหน้ากัน",example:"Many students prefer face-to-face learning.",topic:"Education",level:"B1"},{en:"rarely",th:"แทบจะไม่",example:"Free apps rarely offer real conversations.",ipa:"/ˈreə.li/",topic:"Education",level:"B1"}]},{id:"R3",title:"How Cities Are Changing",level:"B1+",topic:"Cities",focusTh:"Skimming (อ่านเร็วเอาภาพรวม) เพื่อจับคู่หัวข้อ (matching headings) และ scanning หาข้อมูลเฉพาะ",minutes:15,paragraphs:[{label:"A",text:"In 1950, less than a third of the world's population lived in cities. Today, the figure is more than half, and the United Nations expects it to reach nearly 70 percent by 2050. Most of this growth is happening in Asia and Africa."},{label:"B",text:"Rapid growth brings serious challenges. Housing often becomes expensive, roads become crowded, and in some places new residents have to live in informal settlements without clean water or electricity."},{label:"C",text:"To deal with these problems, some cities are investing in public transport. Bogot\xe1 in Colombia, for example, built a bus rapid transit system with special lanes, which carries more than two million passengers a day at a fraction of the cost of an underground railway."},{label:"D",text:"Technology also plays a part. Sensors can measure traffic and air pollution in real time, allowing city managers to change traffic lights or warn residents on days when the air is unhealthy."},{label:"E",text:"Nevertheless, experts warn that technology alone cannot solve urban problems. Good planning, they argue, must start by asking residents what they actually need."}],questionGroups:[{instructions:"Choose the correct heading for each paragraph.",questions:[{id:"q1",kind:"mcq",qtype:"matching-headings",prompt:"Paragraph B",options:["Problems caused by fast growth","A cheaper way to move people","Listening to the people who live there","Using data to manage cities","The rise of the city"],answer:["Problems caused by fast growth"],explanationTh:"'Rapid growth brings serious challenges' → challenges = problems, rapid = fast",evidence:"Rapid growth brings serious challenges."},{id:"q2",kind:"mcq",qtype:"matching-headings",prompt:"Paragraph C",options:["Problems caused by fast growth","A cheaper way to move people","Listening to the people who live there","Using data to manage cities","The rise of the city"],answer:["A cheaper way to move people"],explanationTh:"ระบบรถบัส 'at a fraction of the cost' = ถูกกว่ามาก",evidence:"at a fraction of the cost of an underground railway"},{id:"q3",kind:"mcq",qtype:"matching-headings",prompt:"Paragraph D",options:["Problems caused by fast growth","A cheaper way to move people","Listening to the people who live there","Using data to manage cities","The rise of the city"],answer:["Using data to manage cities"],explanationTh:"sensors measure traffic and pollution = ใช้ข้อมูล (data)",evidence:"Sensors can measure traffic and air pollution in real time"},{id:"q4",kind:"mcq",qtype:"matching-headings",prompt:"Paragraph E",options:["Problems caused by fast growth","A cheaper way to move people","Listening to the people who live there","Using data to manage cities","The rise of the city"],answer:["Listening to the people who live there"],explanationTh:"'asking residents what they actually need' = listening to the people who live there",evidence:"asking residents what they actually need"}]},{instructions:"Scan the passage. Write NO MORE THAN TWO WORDS AND/OR A NUMBER.",questions:[{id:"q5",kind:"text",qtype:"scanning",prompt:"By 2050, nearly ______ percent of people may live in cities.",answer:["70","seventy"],limit:"A NUMBER",explanationTh:"สแกนหาปี 2050 ในย่อหน้า A",evidence:"reach nearly 70 percent by 2050"},{id:"q6",kind:"text",qtype:"scanning",prompt:"Bogot\xe1's bus system carries more than ______ passengers a day.",answer:["two million","2 million","2,000,000","2000000"],limit:"NO MORE THAN TWO WORDS AND/OR A NUMBER",explanationTh:"สแกนหาคำว่า Bogot\xe1 แล้วอ่านตัวเลข",evidence:"carries more than two million passengers a day"}]}],vocab:[{en:"rapid",th:"รวดเร็ว",example:"Rapid growth brings challenges.",ipa:"/ˈr\xe6p.ɪd/",topic:"Cities",level:"B2"},{en:"invest in",th:"ลงทุนใน",example:"Cities are investing in public transport.",topic:"Cities",level:"B1"},{en:"a fraction of the cost",th:"ด้วยต้นทุนเพียงส่วนน้อย",example:"The system cost a fraction of the cost of a railway.",topic:"Cities",level:"B2"},{en:"nevertheless",th:"อย่างไรก็ตาม",example:"Nevertheless, technology alone is not enough.",ipa:"/ˌnev.ə.\xf0əˈles/",topic:"Linking",level:"B2"}]},{id:"R4",title:"Why Cities Need Trees",level:"B1+",topic:"Environment",focusTh:"เดาความหมายคำศัพท์จากบริบท (vocabulary in context) และเติมประโยค (sentence completion)",minutes:15,paragraphs:[{label:"A",text:"Street trees are often seen as decoration, but research shows they provide real economic and health benefits. A single large tree can lower the temperature of the air around it by several degrees on a hot day."},{label:"B",text:"Trees also improve air quality. Their leaves trap dust and absorb some pollutants, although the effect is modest compared with reducing traffic. In addition, streets with trees tend to have lower levels of noise."},{label:"C",text:"There are social benefits as well. In one study in Chicago, apartment buildings surrounded by greenery had fewer reported crimes than similar buildings with little vegetation. The researchers believe that green spaces encourage people to spend time outdoors, which makes streets feel safer."},{label:"D",text:"Despite these advantages, planting trees is not always straightforward. Roots can damage pavements and pipes, and young trees need regular watering for their first three years. For this reason, some cities now ask local residents to 'adopt' a tree and look after it."}],questionGroups:[{instructions:"Choose the correct answer.",questions:[{id:"q1",kind:"mcq",qtype:"vocab-in-context",prompt:"In paragraph B, 'modest' means…",options:["very large","fairly small","dangerous"],answer:["fairly small"],explanationTh:"ดูบริบท: 'compared with reducing traffic' — ผลของต้นไม้น้อยกว่าการลดการจราจร จึงแปลว่า 'ไม่มาก'",evidence:"the effect is modest compared with reducing traffic"},{id:"q2",kind:"mcq",qtype:"vocab-in-context",prompt:"In paragraph D, 'straightforward' is closest in meaning to…",options:["simple","expensive","popular"],answer:["simple"],explanationTh:"ประโยคถัดไปบอกปัญหา (roots damage pavements) แปลว่าการปลูกต้นไม้ 'ไม่ง่าย' → straightforward = simple",evidence:"planting trees is not always straightforward"}]},{instructions:"Complete the sentences. Write NO MORE THAN TWO WORDS from the passage.",questions:[{id:"q3",kind:"text",qtype:"sentence-completion",prompt:"Tree leaves can trap ______ and absorb some pollutants.",answer:["dust"],limit:"NO MORE THAN TWO WORDS",explanationTh:"คำตอบต้องมาจากบทความ และถูกไวยากรณ์ในประโยค",evidence:"Their leaves trap dust"},{id:"q4",kind:"text",qtype:"sentence-completion",prompt:"Young trees must be watered regularly for their first ______.",answer:["three years","3 years"],limit:"NO MORE THAN TWO WORDS",explanationTh:"three years = 2 คำ อยู่ในขีดจำกัด",evidence:"regular watering for their first three years"}]},{instructions:"TRUE, FALSE or NOT GIVEN?",questions:[{id:"q5",kind:"mcq",qtype:"tfng",prompt:"Trees reduce air pollution more than reducing traffic does.",options:["True","False","Not Given"],answer:["False"],explanationTh:"ผลของต้นไม้ 'modest compared with reducing traffic' = น้อยกว่า → ขัดแย้ง FALSE",evidence:"the effect is modest compared with reducing traffic"},{id:"q6",kind:"mcq",qtype:"tfng",prompt:"The Chicago study found fewer reported crimes near greenery.",options:["True","False","Not Given"],answer:["True"],explanationTh:"ตรงกับข้อมูลในย่อหน้า C",evidence:"had fewer reported crimes than similar buildings"},{id:"q7",kind:"mcq",qtype:"tfng",prompt:"Residents who adopt a tree receive money from the city.",options:["True","False","Not Given"],answer:["Not Given"],explanationTh:"บทความไม่ได้บอกว่าได้เงินหรือไม่ → NOT GIVEN",evidence:"(ไม่มีข้อมูลเรื่องเงิน)"}]}],vocab:[{en:"pollutant",th:"สารมลพิษ",example:"Leaves absorb some pollutants.",ipa:"/pəˈluː.tənt/",topic:"Environment",level:"B2"},{en:"modest",th:"ไม่มาก, พอประมาณ",example:"The effect is modest.",ipa:"/ˈmɒd.ɪst/",topic:"Academic",level:"B2"},{en:"straightforward",th:"ตรงไปตรงมา, ง่าย",example:"The process is not always straightforward.",ipa:"/ˌstreɪtˈfɔː.wəd/",topic:"Academic",level:"B2"},{en:"look after",th:"ดูแล",example:"Residents look after the trees.",topic:"Daily life",level:"A2"}]},{id:"R5",title:"Why We Forget",level:"B1+",topic:"Health",focusTh:"Summary completion: เติมคำในบทสรุปจากรายการคำ — คำในบทสรุปจะถูก paraphrase",minutes:12,paragraphs:[{label:"A",text:"In the 1880s, the German psychologist Hermann Ebbinghaus tested his own memory by learning lists of nonsense words. He found that he forgot about half of the new information within an hour, and most of it within a week. This pattern is now called the 'forgetting curve'."},{label:"B",text:"Ebbinghaus also discovered that reviewing information at increasing intervals slows down forgetting. Each time we successfully recall something, the memory becomes stronger and lasts longer. This idea is the basis of modern 'spaced repetition' apps."},{label:"C",text:"Sleep matters too. During sleep, the brain appears to replay and organise information learned during the day. Students who sleep after studying usually remember more than those who stay awake for the same length of time."}],questionGroups:[{instructions:"Complete the summary using words from the box: week, hour, intervals, stronger, weaker, sleep, coffee, lists.",questions:[{id:"q1",kind:"text",qtype:"summary-completion",prompt:"Ebbinghaus forgot about half of new information within an ______.",answer:["hour"],limit:"ONE WORD",explanationTh:"within an hour (ไม่ใช่ week ซึ่งเป็นช่วงที่ลืม 'ส่วนใหญ่')",evidence:"forgot about half of the new information within an hour"},{id:"q2",kind:"text",qtype:"summary-completion",prompt:"Reviewing at growing ______ slows down forgetting.",answer:["intervals"],limit:"ONE WORD",explanationTh:"increasing intervals → growing intervals (paraphrase)",evidence:"reviewing information at increasing intervals slows down forgetting"},{id:"q3",kind:"text",qtype:"summary-completion",prompt:"Successful recall makes a memory ______.",answer:["stronger"],limit:"ONE WORD",explanationTh:"the memory becomes stronger",evidence:"the memory becomes stronger and lasts longer"},{id:"q4",kind:"text",qtype:"summary-completion",prompt:"Students who ______ after studying usually remember more.",answer:["sleep"],limit:"ONE WORD",explanationTh:"ย่อหน้า C",evidence:"Students who sleep after studying usually remember more"}]},{instructions:"Choose the correct answer.",questions:[{id:"q5",kind:"mcq",qtype:"main-idea",prompt:"What is the main purpose of the passage?",options:["To criticise Ebbinghaus's research","To explain why we forget and how to remember better","To advertise a language app"],answer:["To explain why we forget and how to remember better"],explanationTh:"ทั้งบทอธิบายการลืมและวิธีช่วยจำ ไม่ได้วิจารณ์หรือโฆษณา",evidence:"This idea is the basis of modern 'spaced repetition' apps."}]}],vocab:[{en:"recall",th:"นึกออก, ระลึกได้",example:"Each time we recall something, the memory gets stronger.",ipa:"/rɪˈkɔːl/",topic:"Education",level:"B2"},{en:"interval",th:"ช่วงเวลาห่าง",example:"Review words at increasing intervals.",ipa:"/ˈɪn.tə.vəl/",topic:"Academic",level:"B2"},{en:"psychologist",th:"นักจิตวิทยา",example:"Ebbinghaus was a German psychologist.",ipa:"/saɪˈkɒl.ə.dʒɪst/",topic:"Academic",level:"B2"}]},{id:"R6",title:"Desalination: Promise and Problems (IELTS-style)",level:"IELTS-style",topic:"Environment",focusTh:"แบบฝึกสไตล์ IELTS Academic: Yes/No/Not Given (ความเห็นผู้เขียน) และ matching headings ภายใต้เวลาจำกัด",minutes:20,paragraphs:[{label:"A",text:"As populations grow and droughts become more frequent, an increasing number of countries are turning to the sea for drinking water. Desalination, the process of removing salt from seawater, now supplies water to more than 300 million people worldwide, mainly in the Middle East, North Africa and Australia."},{label:"B",text:"The dominant technology, reverse osmosis, pushes seawater through membranes that allow water molecules to pass but block salt. Although the membranes have become far more efficient since the 1970s, the process still requires large amounts of electricity. In my view, this energy cost is the single greatest obstacle to wider use, particularly where electricity comes from fossil fuels."},{label:"C",text:"A second concern is brine, the very salty liquid left behind. For every litre of fresh water produced, plants typically generate around one and a half litres of brine, which is usually returned to the sea. Where it is not properly diluted, it can harm organisms living on the seabed."},{label:"D",text:"Supporters argue that these problems can be managed. Plants increasingly run on solar power, and engineers are experimenting with extracting useful minerals from brine. Such developments are encouraging, yet it would be unwise to treat desalination as a complete solution. Reducing leaks in existing water pipes, which in some cities lose a quarter of their supply, is often a cheaper first step."}],questionGroups:[{instructions:"Choose the correct heading for paragraphs B–D.",questions:[{id:"q1",kind:"mcq",qtype:"matching-headings",prompt:"Paragraph B",options:["A waste product and its effects","Why demand for desalination is rising","How the main method works and its key weakness","Possible improvements and a cheaper alternative"],answer:["How the main method works and its key weakness"],explanationTh:"ย่อหน้า B อธิบาย reverse osmosis + ปัญหาพลังงาน (obstacle = weakness)",evidence:"this energy cost is the single greatest obstacle"},{id:"q2",kind:"mcq",qtype:"matching-headings",prompt:"Paragraph C",options:["A waste product and its effects","Why demand for desalination is rising","How the main method works and its key weakness","Possible improvements and a cheaper alternative"],answer:["A waste product and its effects"],explanationTh:"brine = ของเสียที่เหลือ และ 'can harm organisms' = ผลกระทบ",evidence:"brine, the very salty liquid left behind"},{id:"q3",kind:"mcq",qtype:"matching-headings",prompt:"Paragraph D",options:["A waste product and its effects","Why demand for desalination is rising","How the main method works and its key weakness","Possible improvements and a cheaper alternative"],answer:["Possible improvements and a cheaper alternative"],explanationTh:"solar power, extracting minerals = improvements; reducing leaks = cheaper first step",evidence:"Reducing leaks … is often a cheaper first step."}]},{instructions:"Do the following statements agree with the views of the writer? Choose YES, NO or NOT GIVEN.",questions:[{id:"q4",kind:"mcq",qtype:"ynng",prompt:"Energy use is the biggest barrier to desalination becoming more widespread.",options:["Yes","No","Not Given"],answer:["Yes"],explanationTh:"'In my view' = ความเห็นผู้เขียน และ greatest obstacle = biggest barrier → YES",evidence:"In my view, this energy cost is the single greatest obstacle to wider use"},{id:"q5",kind:"mcq",qtype:"ynng",prompt:"Desalination can completely solve water shortages.",options:["Yes","No","Not Given"],answer:["No"],explanationTh:"ผู้เขียนบอกว่า 'unwise to treat desalination as a complete solution' ขัดแย้งกับข้อความ → NO",evidence:"it would be unwise to treat desalination as a complete solution"},{id:"q6",kind:"mcq",qtype:"ynng",prompt:"Governments should pay for desalination plants rather than private companies.",options:["Yes","No","Not Given"],answer:["Not Given"],explanationTh:"ผู้เขียนไม่ได้แสดงความเห็นเรื่องใครควรจ่าย → NOT GIVEN",evidence:"(ไม่มีความเห็นเรื่องนี้)"}]},{instructions:"Complete the sentences. Write NO MORE THAN TWO WORDS AND/OR A NUMBER from the passage.",questions:[{id:"q7",kind:"text",qtype:"sentence-completion",prompt:"Desalination supplies water to over ______ people.",answer:["300 million","three hundred million"],limit:"NO MORE THAN TWO WORDS AND/OR A NUMBER",explanationTh:"300 million",evidence:"more than 300 million people worldwide"},{id:"q8",kind:"text",qtype:"sentence-completion",prompt:"Some city pipes lose a ______ of their water through leaks.",answer:["quarter"],limit:"ONE WORD",explanationTh:"a quarter = หนึ่งในสี่",evidence:"lose a quarter of their supply"}]}],vocab:[{en:"drought",th:"ภัยแล้ง",example:"Droughts are becoming more frequent.",ipa:"/draʊt/",topic:"Environment",level:"B2"},{en:"obstacle",th:"อุปสรรค",example:"Cost is the greatest obstacle.",ipa:"/ˈɒb.stə.kəl/",topic:"Academic",level:"B2"},{en:"dominant",th:"ที่มีอิทธิพล/ใช้มากที่สุด",example:"Reverse osmosis is the dominant technology.",ipa:"/ˈdɒm.ɪ.nənt/",topic:"Academic",level:"C1"},{en:"unwise",th:"ไม่ฉลาด, ไม่ควร",example:"It would be unwise to rely on one solution.",topic:"Academic",level:"B2"}]}];function n(e){return e.questionGroups.flatMap(e=>e.questions)}}}]);